function todayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
const defaults={gameMinutes:360,coins:250,gold:0,xp:0,level:1,caught:0,best:0,health:100,hunger:100,rawFish:0,ingredients:{salt:2,oil:1,potato:1,herbs:1},spot:0,unlocked:[0],clothes:{owned:[0],equipped:0},gear:{rod:0,line:0,reel:0,hook:0},gearOwned:{rod:[0],line:[0],reel:[0],hook:[0]},daily:{date:todayKey(),progress:{crucian:0,any:0,cook:0,spotCounts:{}},claimed:{crucian:false,any:false,cook:false}},trophies:{},achievements:{},pendingCatch:null,baits:{worm:10,bread:10,corn:0,spinner:0,minnow:0,garlic:0,cheese:0,boilie:0},selectedBait:'worm',castPower:70,fishCaught:{},history:[],casts:0,lineDurability:100,rodDurability:100,reelDurability:100,questClaimed:false,questProgress:0,cookedTotal:0};
let state=load(),mode='idle',fish=null,fishWeight=0,fishEnergy=0,tension=0,actionTick=0,toastTimer=0,lastFrame=0,particles=[],sceneTime=0,currentWeather='clear',castAnimStart=0;
function load(){try{const raw=JSON.parse(localStorage.getItem('odyssey-save')||'{}');return {...structuredClone(defaults),...raw,gameMinutes:Math.max(0,Number(raw.gameMinutes)||360),health:Math.max(0,Math.min(100,Number.isFinite(Number(raw.health))?Number(raw.health):100)),hunger:Math.max(0,Math.min(100,Number.isFinite(Number(raw.hunger))?Number(raw.hunger):100)),rawFish:Math.max(0,Number(raw.rawFish)||0),ingredients:{...defaults.ingredients,...(raw.ingredients||{})},castPower:Math.max(25,Math.min(100,Number(raw.castPower)||70)),lineDurability:Math.max(0,Math.min(100,Number.isFinite(Number(raw.lineDurability))?Number(raw.lineDurability):100)),rodDurability:Math.max(0,Math.min(100,Number.isFinite(Number(raw.rodDurability))?Number(raw.rodDurability):100)),reelDurability:Math.max(0,Math.min(100,Number.isFinite(Number(raw.reelDurability))?Number(raw.reelDurability):100)),gear:{...defaults.gear,...(raw.gear||{})},gearOwned:Object.fromEntries(GEAR.map(g=>[g.id,Array.isArray(raw.gearOwned&&raw.gearOwned[g.id])?raw.gearOwned[g.id]:Array.from({length:Math.max(0,Number((raw.gear||{})[g.id]||0)+1)},(_,i)=>i)])),daily:raw.daily&&raw.daily.date===todayKey()?{...defaults.daily,...raw.daily,progress:{...defaults.daily.progress,...(raw.daily.progress||{}),spotCounts:{...((raw.daily.progress||{}).spotCounts||{})}},claimed:{...defaults.daily.claimed,...(raw.daily.claimed||{})}}:structuredClone(defaults.daily),clothes:{...defaults.clothes,...(raw.clothes||{}),owned:Array.isArray(raw.clothes&&raw.clothes.owned)?raw.clothes.owned:[0]},baits:{...defaults.baits,...(raw.baits||{})},fishCaught:{...(raw.fishCaught||{})},trophies:{...(raw.trophies||{})},achievements:{...(raw.achievements||{})},pendingCatch:raw.pendingCatch||null,unlocked:Array.isArray(raw.unlocked)?raw.unlocked:[0],history:Array.isArray(raw.history)?raw.history:[]}}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem('odyssey-save',JSON.stringify(state));renderAll()}
function fmt(n){return Number(n).toLocaleString('ru-RU',{maximumFractionDigits:1})}
function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function gearPower(){return ['rod','line','reel'].reduce((p,k)=>p*GEAR.find(g=>g.id===k).items[state.gear[k]||0].power,1)*CLOTHES[state.clothes.equipped||0].power}
function hookPower(){return GEAR.find(g=>g.id==='hook').items[state.gear.hook||0].power}
function tackleStrength(){const rod=GEAR.find(g=>g.id==='rod').items[state.gear.rod||0].power,line=GEAR.find(g=>g.id==='line').items[state.gear.line||0].power,reel=GEAR.find(g=>g.id==='reel').items[state.gear.reel||0].power,hook=hookPower(),clothes=CLOTHES[state.clothes.equipped||0].power;return Math.pow(rod*line*reel*hook*clothes,1/5)}
function hookLimit(){return [3,10,25,60][state.gear.hook||0]}
function gainXP(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.coins+=state.level*35;notify('Новый уровень '+state.level+'! Бонус: '+state.level*35+' 🪙')}}
function renderSurvival(){const hp=Math.max(0,Math.min(100,state.health)),food=Math.max(0,Math.min(100,state.hunger));if($('healthNum'))$('healthNum').textContent=Math.round(hp)+'%';if($('hungerNum'))$('hungerNum').textContent=Math.round(food)+'%';if($('healthBar'))$('healthBar').style.width=hp+'%';if($('hungerBar'))$('hungerBar').style.width=food+'%';if($('healthBar'))$('healthBar').style.background=hp<30?'linear-gradient(90deg,#ff6c63,#ffb36b)':'linear-gradient(90deg,#ff6c63,#70dfa4)';if($('hungerBar'))$('hungerBar').style.background=food<30?'linear-gradient(90deg,#ff6c63,#ffd36b)':'linear-gradient(90deg,#e6a85d,#ffe08a)';const note=state.health<=0?'Силы закончились — приготовь еду на кухне!':state.hunger<=0?'Ты голодаешь: здоровье постепенно снижается.':state.hunger<25?'Скоро понадобится еда.':'Ты сыт и полон сил.';if($('survivalNote'))$('survivalNote').textContent=note;if($('kitchenHealthNum'))$('kitchenHealthNum').textContent=Math.round(hp)+'%';if($('kitchenHungerNum'))$('kitchenHungerNum').textContent=Math.round(food)+'%';if($('kitchenHealthBar'))$('kitchenHealthBar').style.width=hp+'%';if($('kitchenHungerBar'))$('kitchenHungerBar').style.width=food+'%';if($('kitchenSurvivalNote'))$('kitchenSurvivalNote').textContent=note}
function gameClockText(){const total=Math.floor(Math.max(0,Number(state.gameMinutes)||0)),day=Math.floor(total/1440)+1,hour=Math.floor((total%1440)/60),minute=total%60;return '🕒 День '+day+' · '+String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0')}
function renderHeader(){$('gameClock').textContent=gameClockText();$('coins').textContent=fmt(state.coins);if($('gold'))$('gold').textContent=fmt(Number(state.gold)||0);$('playerLevel').textContent='Уровень '+state.level;$('xpText').textContent=state.xp+' / '+state.level*100;$('xpBar').style.width=(state.xp/(state.level*100)*100)+'%';$('spotName').textContent=SPOTS[state.spot].name}
function renderBaits(){$('baitList').innerHTML=BAITS.map(b=>'<button class="bait '+(state.selectedBait===b.id?'active':'')+'" data-bait="'+b.id+'"><span class="emoji">'+b.emoji+'</span>'+b.name+'<br><small>'+state.baits[b.id]+' шт.</small></button>').join('');$('baitList').querySelectorAll('[data-bait]').forEach(b=>b.onclick=()=>{const id=b.dataset.bait;if(!state.baits[id]){notify('Эта приманка закончилась. Купи запас в магазине.');showScreen('shop');return}state.selectedBait=id;save()});$('gearSummary').innerHTML=GEAR.map(g=>'<div class="gearbit"><span>'+g.emoji+'</span><small>'+g.name+'</small><b>'+g.items[state.gear[g.id]].name+'</b></div>').join('')}
function renderSpots(){$('spotList').innerHTML=SPOTS.map(s=>{const unlocked=state.unlocked.includes(s.id),can=s.premium?(Number(state.gold)||0)>=s.cost:state.level>=s.level&&state.coins>=s.cost;return '<div class="card spotcard"><div class="spotemoji">'+s.emoji+'</div><div class="itembody"><h3>'+s.name+(state.spot===s.id?' <span class="selectedtag">• ВЫБРАНО</span>':'')+'</h3><p>'+s.desc+'</p><div class="itemmeta">🐟 '+s.fish+' · Уровень '+s.level+'</div></div>'+(unlocked?'<button class="smallbtn" data-spot="'+s.id+'">'+(state.spot===s.id?'Выбрано':'Выбрать')+'</button>':'<button class="smallbtn" data-unlock="'+s.id+'" '+(!can?'disabled':'')+'>'+s.cost+(s.premium?' ✨':' 🪙')+'</button>')+'</div>'}).join('');$('spotList').querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{state.spot=+b.dataset.spot;mode='idle';save();notify('Место рыбалки изменено')});$('spotList').querySelectorAll('[data-unlock]').forEach(b=>b.onclick=()=>{const s=SPOTS[+b.dataset.unlock];if(s.premium){if((Number(state.gold)||0)<s.cost)return;state.gold-=s.cost}else{if(state.level<s.level||state.coins<s.cost)return;state.coins-=s.cost}state.unlocked.push(s.id);state.spot=s.id;save();notify('Новый водоём открыт!')})}
function compactShop(){const root=$('shopList');if(!root)return;[...root.querySelectorAll(':scope > .section-title')].forEach(title=>{const d=document.createElement('details');d.className='shop-category';const s=document.createElement('summary');s.innerHTML=title.innerHTML+'<span class="category-count">Открыть ▾</span>';d.appendChild(s);const body=document.createElement('div');body.className='shop-category-body';let n=title.nextElementSibling;while(n&&!n.classList.contains('section-title')){const next=n.nextElementSibling;body.appendChild(n);n=next}d.appendChild(body);const label=s.textContent.toLowerCase();d.dataset.shopTab=label.includes('приман')?'bait':label.includes('одежд')?'clothes':label.includes('премиум')||label.includes('золото')?'gold':'gear';title.replaceWith(d);s.addEventListener('click',()=>{const c=s.querySelector('.category-count');if(c)c.textContent=d.open?'Скрыть ▴':'Открыть ▾'})});let tabs=root.querySelector('.shop-tabs');if(!tabs){tabs=document.createElement('div');tabs.className='shop-tabs';tabs.setAttribute('role','tablist');tabs.innerHTML='<button class="shop-tab active" data-shop-tab="gear" role="tab">🎣 Снасти</button><button class="shop-tab" data-shop-tab="bait" role="tab">🪱 Наживка</button><button class="shop-tab" data-shop-tab="clothes" role="tab">👕 Одежда</button><button class="shop-tab" data-shop-tab="gold" role="tab">✨ Золото</button>';root.prepend(tabs);tabs.querySelectorAll('[data-shop-tab]').forEach(b=>b.addEventListener('click',()=>{tabs.querySelectorAll('.shop-tab').forEach(x=>x.classList.toggle('active',x===b));root.querySelectorAll(':scope > .shop-category').forEach(d=>{d.hidden=d.dataset.shopTab!==b.dataset.shopTab;d.open=false;const c=d.querySelector('.category-count');if(c)c.textContent='Открыть ▾'})}))}const active=tabs.querySelector('.shop-tab.active')?.dataset.shopTab||'gear';root.querySelectorAll(':scope > .shop-category').forEach(d=>d.hidden=d.dataset.shopTab!==active);root.dataset.compact='yes'}
function renderShop(){$('shopList').innerHTML=GEAR.map(g=>'<div class="section-title"><h2>'+g.emoji+' '+g.name+'</h2></div>'+g.items.map((it,i)=>{const owned=state.gearOwned[g.id].includes(i),current=i===state.gear[g.id]&&owned,maxOwned=state.gearOwned[g.id].length?Math.max(...state.gearOwned[g.id]):-1;let action=current?'<span class="selectedtag">НАДЕТО</span>':owned?'<button class="smallbtn" data-equip-gear="'+g.id+'" data-index="'+i+'">Надеть</button>':i===maxOwned+1&&state.coins>=it.cost?'<button class="smallbtn" data-buy="'+g.id+'" data-index="'+i+'">'+it.cost+' 🪙 · Купить</button>':'<span class="gear-locked">🔒 '+it.cost+' 🪙</span>';return '<div class="card shopitem"><div class="itememoji">'+g.emoji+'</div><div class="itembody"><h3>'+it.name+'</h3><p>'+it.desc+'</p><div class="itemmeta">Мощность ×'+it.power+'</div></div>'+action+'</div>'}).join('')).join('');$('shopList').insertAdjacentHTML('beforeend','<div class="section-title"><h2>🪱 Приманки</h2><span>Пачки по 5 шт.</span></div>'+BAITS.map(b=>'<div class="card shopitem bait-shop-item"><div class="itememoji">'+b.emoji+'</div><div class="itembody"><h3>'+b.name+'</h3><p>'+b.desc+'</p><div class="itemmeta">В запасе: '+state.baits[b.id]+' шт. · '+b.cost+' 🪙 за штуку</div></div><button class="smallbtn" data-buy-bait="'+b.id+'">Купить 5 · '+(b.cost*5)+' 🪙</button></div>').join('')+'<div class="section-title"><h2>🧺 Ингредиенты</h2><span>Для готовки дома</span></div>'+INGREDIENTS.map(x=>'<div class="card shopitem"><div class="itememoji">'+x.emoji+'</div><div class="itembody"><h3>'+x.name+'</h3><p>'+x.desc+'</p><div class="itemmeta">В запасе: '+(state.ingredients[x.id]||0)+' шт. · '+x.cost+' 🪙 за штуку</div></div><button class="smallbtn" data-buy-ingredient="'+x.id+'">Купить 3 · '+(x.cost*3)+' 🪙</button></div>').join('')+'<div class="section-title"><h2>👕 Одежда</h2><span>Бонусы к вываживанию</span></div>'+CLOTHES.map(c=>{const owned=state.clothes.owned.includes(c.id),equipped=state.clothes.equipped===c.id;return '<div class="card shopitem clothes-item"><div class="itememoji">'+c.emoji+'</div><div class="itembody"><h3>'+c.name+'</h3><p>'+c.desc+'</p><div class="itemmeta">Бонус ×'+c.power+'</div></div>'+(equipped?'<span class="selectedtag">НАДЕТО</span>':owned?'<button class="smallbtn" data-equip-clothes="'+c.id+'">Надеть</button>':'<button class="smallbtn" data-buy-clothes="'+c.id+'" '+(state.coins<c.cost?'disabled':'')+'>'+c.cost+' 🪙</button>')+'</div>'}).join(''));$('shopList').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const g=GEAR.find(x=>x.id===b.dataset.buy),i=+b.dataset.index,it=g.items[i],owned=state.gearOwned[g.id],maxOwned=Math.max(...owned);if(owned.includes(i)||i!==maxOwned+1||state.coins<it.cost)return;state.coins-=it.cost;owned.push(i);state.gear[g.id]=i;if(g.id==='rod')state.rodDurability=100;if(g.id==='line')state.lineDurability=100;if(g.id==='reel')state.reelDurability=100;save();notify('Куплено и надето: '+it.name)});$('shopList').querySelectorAll('[data-equip-gear]').forEach(b=>b.onclick=()=>{const g=GEAR.find(x=>x.id===b.dataset.equipGear),i=+b.dataset.index;if(!g||!state.gearOwned[g.id].includes(i))return;state.gear[g.id]=i;if(g.id==='rod')state.rodDurability=100;if(g.id==='line')state.lineDurability=100;if(g.id==='reel')state.reelDurability=100;save();notify('Надето: '+g.items[i].name)});$('shopList').querySelectorAll('[data-buy-bait]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyBait,bait=BAITS.find(x=>x.id===id),price=bait.cost*5;if(state.coins<price){notify('Не хватает монет на эту пачку.');return}state.coins-=price;state.baits[id]=(state.baits[id]||0)+5;save();notify('Куплено 5 шт.: '+bait.name)});$('shopList').querySelectorAll('[data-buy-ingredient]').forEach(b=>b.onclick=()=>{const item=INGREDIENTS.find(x=>x.id===b.dataset.buyIngredient),qty=3,price=item.cost*qty;if(state.coins<price){notify('Не хватает монет на ингредиенты.');return}state.coins-=price;state.ingredients[item.id]=(state.ingredients[item.id]||0)+qty;save();notify('Куплено: '+item.name+' ×'+qty)});$('shopList').querySelectorAll('[data-buy-clothes]').forEach(b=>b.onclick=()=>{const id=+b.dataset.buyClothes,c=CLOTHES[id];if(state.coins<c.cost||state.clothes.owned.includes(id))return;state.coins-=c.cost;state.clothes.owned.push(id);state.clothes.equipped=id;save();notify('Куплен и надет комплект: '+c.name)});$('shopList').querySelectorAll('[data-equip-clothes]').forEach(b=>b.onclick=()=>{state.clothes.equipped=+b.dataset.equipClothes;save();notify('Одежда изменена!')});$('shopList').insertAdjacentHTML('beforeend','<div class="section-title"><h2>✨ Премиум-золото</h2><span>Донат</span></div><div class="card premium-info"><div class="itememoji">✨</div><div class="itembody"><h3>Золото — премиальная валюта</h3><p>Золото не продаётся за обычные монеты и не выдаётся за уровни. Покупка за реальные деньги появится после подключения платёжной системы. Сейчас небольшое количество можно случайно найти только в пруду «Золотая форель».</p><div class="itemmeta">Баланс: '+fmt(Number(state.gold)||0)+' ✨ · Пруд открывается с 12 уровня за 2500 🪙</div></div></div>');compactShop()}
function renderKitchen(){renderSurvival();const stock={rawFish:state.rawFish,...state.ingredients};$('kitchenStock').innerHTML='<div class="stock-chip">🐟 <b>'+stock.rawFish+'</b><span>порций рыбы</span></div>'+INGREDIENTS.map(x=>'<div class="stock-chip">'+x.emoji+' <b>'+Math.max(0,Number(stock[x.id])||0)+'</b><span>'+x.name+'</span></div>').join('');$('recipeList').innerHTML=RECIPES.map(r=>{const can=Object.entries(r.need).every(([k,v])=>(Number(stock[k])||0)>=v);const needs=Object.entries(r.need).map(([k,v])=>{const item=k==='rawFish'?{name:'рыба',emoji:'🐟'}:INGREDIENTS.find(x=>x.id===k);return item.emoji+' '+item.name+' ×'+v}).join(' · ');return '<div class="card recipe-card"><div class="recipe-head"><span>'+r.emoji+'</span><div><h3>'+r.name+'</h3><p>'+r.desc+'</p></div></div><p class="recipe-needs">'+needs+'</p><div class="recipe-benefit">❤️ +'+r.health+' здоровья · 🍗 +'+r.hunger+' сытости</div><button class="smallbtn cook-btn" data-cook="'+r.id+'" '+(!can?'disabled':'')+'>👨‍🍳 Приготовить</button></div>'}).join('');$('recipeList').querySelectorAll('[data-cook]').forEach(b=>b.onclick=()=>{const r=RECIPES.find(x=>x.id===b.dataset.cook);if(!r||!Object.entries(r.need).every(([k,v])=>(Number(k==='rawFish'?state.rawFish:state.ingredients[k])||0)>=v)){notify('Не хватает ингредиентов для рецепта.');return}for(const [k,v] of Object.entries(r.need)){if(k==='rawFish')state.rawFish-=v;else state.ingredients[k]-=v}state.health=Math.min(100,state.health+r.health);state.hunger=Math.min(100,state.hunger+r.hunger);state.daily.progress.cook=(state.daily.progress.cook||0)+1;state.cookedTotal=(state.cookedTotal||0)+1;checkAchievements();save();renderKitchen();notify('Приготовлено: '+r.name+'!')})}
function renderKeep(){const unique=Object.keys(state.fishCaught).length,trophyCount=Object.values(state.trophies||{}).reduce((a,n)=>a+Number(n||0),0);$('collectionStats').innerHTML='<div class="statbox"><b>'+state.caught+'</b><span>Всего рыб</span></div><div class="statbox"><b>'+fmt(state.best)+' кг</b><span>Рекорд</span></div><div class="statbox"><b>'+unique+'/'+FISH.length+'</b><span>Виды</span></div><div class="statbox"><b>✨ '+trophyCount+'</b><span>Редкие трофеи</span></div>';$('catchList').innerHTML=state.history.length?state.history.slice(0,15).map(h=>'<div class="card catchitem"><div class="itememoji">'+h.emoji+'</div><div class="itembody"><h3>'+(h.rare?'✨ ':'')+h.name+'</h3><p>'+h.spot+' · '+h.time+' · '+(h.disposition||'Улов')+'</p></div><b>'+fmt(h.weight)+' кг</b></div>').join(''):'<div class="empty">Здесь появится твой первый улов. Пора на рыбалку!</div>';$('fishBook').innerHTML=FISH.map(f=>{const known=!!state.fishCaught[f.id],trophies=Number((state.trophies||{})[f.id])||0;return '<div class="fishentry '+(known?'':'locked')+'"><div class="fishemoji">'+(known?f.emoji:'❔')+'</div><h3>'+(known?f.name:'Неизвестная рыба')+'</h3><p>'+(known?f.min+'–'+f.max+' кг':'Поймай её, чтобы открыть')+'</p>'+(trophies?'<small class="trophy-tag">✨ Трофеев: '+trophies+'</small>':'')+'</div>'}).join('')}
const ACHIEVEMENTS=[{id:'first',emoji:'🐟',name:'Первая рыбка',desc:'Поймай первую рыбу',reward:30,check:()=>state.caught>=1},{id:'ten',emoji:'🎣',name:'Рыбак-любитель',desc:'Поймай 10 рыб',reward:80,check:()=>state.caught>=10},{id:'fifty',emoji:'🏅',name:'Мастер водоёма',desc:'Поймай 50 рыб',reward:220,check:()=>state.caught>=50},{id:'rare',emoji:'✨',name:'Охотник за редкостями',desc:'Поймай редкую рыбу',reward:100,check:()=>Object.values(state.trophies||{}).reduce((a,n)=>a+n,0)>=1},{id:'heavy',emoji:'⚖️',name:'Тяжеловес',desc:'Поймай рыбу тяжелее 5 кг',reward:120,check:()=>state.best>=5},{id:'level',emoji:'⭐',name:'Опытный рыбак',desc:'Достигни 5 уровня',reward:180,check:()=>state.level>=5},{id:'explorer',emoji:'🌍',name:'Путешественник',desc:'Открой 3 водоёма',reward:150,check:()=>state.unlocked.length>=3},{id:'casts',emoji:'🎯',name:'Меткий заброс',desc:'Сделай 25 забросов',reward:90,check:()=>state.casts>=25},{id:'chef',emoji:'🍲',name:'Шеф-повар',desc:'Приготовь 10 блюд',reward:150,check:()=>state.cookedTotal>=10}];function checkAchievements(){state.achievements=state.achievements||{};for(const a of ACHIEVEMENTS)if(!state.achievements[a.id]&&a.check()){state.achievements[a.id]=true;state.coins+=a.reward;notify('🏆 Достижение: '+a.name+' · +'+a.reward+' монет')}}function renderAchievements(){const el=$('achievementList');if(!el)return;checkAchievements();el.innerHTML='<div class="achievement-summary">🏆 Открыто '+ACHIEVEMENTS.filter(a=>state.achievements[a.id]).length+' из '+ACHIEVEMENTS.length+' достижений</div>'+ACHIEVEMENTS.map(a=>'<div class="card achievement-card '+(state.achievements[a.id]?'unlocked':'locked')+'"><span class="achievement-icon">'+a.emoji+'</span><div class="itembody"><h3>'+a.name+(state.achievements[a.id]?' ✓':'')+'</h3><p>'+a.desc+'</p><div class="itemmeta">'+(state.achievements[a.id]?'Получено':'Награда: '+a.reward+' 🪙')+'</div></div></div>').join('')}
function renderTasks(){const spot=SPOTS[state.spot]||SPOTS[0],spotId='spot-'+spot.id,seed=Number(todayKey().replace(/-/g,'')),pool=[{id:'any',kind:'any',emoji:'🎣',title:'Удачный день',desc:'Поймай 8 любых рыб',goal:8,reward:90,xp:40,ingredients:{potato:2}},{id:'crucian',kind:'crucian',emoji:'🐠',title:'Карасиный улов',desc:'Поймай 4 карася',goal:4,reward:75,xp:35,ingredients:{salt:2,oil:1}},{id:'bream',kind:'fish-bream',emoji:'🐡',title:'Лещовый патруль',desc:'Поймай 3 леща',goal:3,reward:95,xp:45,ingredients:{herbs:2}},{id:'pike',kind:'fish-pike',emoji:'🐊',title:'Охота на хищника',desc:'Поймай 2 щуки',goal:2,reward:115,xp:55,ingredients:{oil:2}},{id:'cook',kind:'cook',emoji:'🍲',title:'Домашний повар',desc:'Приготовь 2 блюда',goal:2,reward:60,xp:30,ingredients:{herbs:2,salt:1}},{id:'rare',kind:'rare',emoji:'✨',title:'За редким трофеем',desc:'Поймай 1 редкую рыбу',goal:1,reward:160,xp:75,ingredients:{salt:2,potato:1}},{id:spotId,kind:'spot',emoji:spot.emoji,title:'Исследователь: '+spot.name,desc:'Поймай 3 рыбы на водоёме «'+spot.name+'»',goal:3,reward:90+spot.id*20,xp:40+spot.id*5,ingredients:{salt:1,potato:1}},{id:'heavy',kind:'heavy',emoji:'⚖️',title:'Тяжёлый улов',desc:'Поймай рыбу тяжелее 5 кг',goal:1,reward:130,xp:60,ingredients:{oil:2}}],ordered=[...pool.slice(seed%pool.length),...pool.slice(0,seed%pool.length)],dailyDefs=ordered.slice(0,4).map(q=>({...q,progress:q.kind==='any'?(state.daily.progress.any||0):q.kind==='crucian'?(state.daily.progress.crucian||0):q.kind==='cook'?(state.daily.progress.cook||0):q.kind==='spot'?((state.daily.progress.spotCounts||{})[spot.id]||0):q.kind==='rare'?(state.daily.progress.rare||0):q.kind==='heavy'?(state.daily.progress.heavy||0):q.kind==='fish-bream'?((state.daily.progress['fish-bream']||0)):((state.daily.progress['fish-pike']||0))}));$('dailyTaskList').innerHTML=dailyDefs.map(q=>{const p=Math.min(q.goal,Number(q.progress)||0),done=!!state.daily.claimed[q.id];return '<div class="card daily-task"><div class="daily-task-top"><span class="daily-emoji">'+q.emoji+'</span><div class="daily-task-copy"><h3>'+q.title+'</h3><p>'+q.desc+'</p></div><span class="daily-count">'+p+'/'+q.goal+'</span></div><div class="taskprogress"><i style="width:'+(p/q.goal*100)+'%"></i></div><div class="daily-reward">🪙 '+q.reward+' · ✨ '+q.xp+' опыта · '+Object.entries(q.ingredients).map(([id,n])=>INGREDIENTS.find(x=>x.id===id).emoji+' ×'+n).join(' ')+'</div>'+(done?'<span class="selectedtag">ПОЛУЧЕНО ✓</span>':'<button class="smallbtn daily-claim" data-claim-daily="'+q.id+'" '+(p<q.goal?'disabled':'')+'>Забрать награду</button>')+'</div>'}).join('');$('dailyTaskList').querySelectorAll('[data-claim-daily]').forEach(b=>b.onclick=()=>{const q=dailyDefs.find(x=>x.id===b.dataset.claimDaily);if(!q||state.daily.claimed[q.id]||(Number(q.progress)||0)<q.goal)return;state.daily.claimed[q.id]=true;state.coins+=q.reward;gainXP(q.xp);for(const [id,n] of Object.entries(q.ingredients))state.ingredients[id]=(state.ingredients[id]||0)+n;save();notify('Задание выполнено! Награда получена.')});renderAchievements();const goal=5,progress=Math.min(goal,state.questProgress);$('taskCard').innerHTML='<h3>🎯 Первая пятёрка</h3><p>Поймай '+goal+' рыб на любых водоёмах.</p><div class="taskprogress"><i style="width:'+(progress/goal*100)+'%"></i></div><p>'+progress+' / '+goal+' рыб</p>'+(state.questClaimed?'<span class="selectedtag">НАГРАДА ПОЛУЧЕНА ✓</span>':'<button class="btn btn-primary" id="claimTask" '+(progress<goal?'disabled':'')+'>Забрать награду · 100 🪙 + 50 опыта</button>');const b=$('claimTask');if(b)b.onclick=()=>{if(state.questProgress<goal||state.questClaimed)return;state.questClaimed=true;state.coins+=100;gainXP(50);save();notify('Задание выполнено!')};$('recordText').textContent=state.caught?'Самый тяжёлый улов: '+fmt(state.best)+' кг. Всего поймано: '+state.caught+'.':'Поймай первую рыбу, чтобы начать историю рекордов.'}
function reelRepairCost(){return 45+(Number(state.gear.reel)||0)*30}
function rodRepairCost(){return 60+(Number(state.gear.rod)||0)*35}
function renderDurability(){const items=[['lineDurability','lineDurabilityNum','line',35],['rodDurability','rodDurabilityNum','rod',rodRepairCost()],['reelDurability','reelDurabilityNum','reel',reelRepairCost()]];for(const [barId,labelId,key,cost] of items){const value=Math.max(0,Math.min(100,Number(state[key+'Durability'])||0));const bar=$(barId),label=$(labelId);if(bar)bar.style.width=value+'%';if(label)label.textContent=Math.round(value)+'%';const repair=$('repair'+key[0].toUpperCase()+key.slice(1)+'Btn');if(repair){repair.disabled=value>=100||state.coins<cost;repair.textContent=value>=100?({line:'🧵 Леска исправна',rod:'🎣 Удочка исправна',reel:'⚙️ Катушка исправна'}[key]):({line:'🧰 Починить леску',rod:'🔧 Починить удочку',reel:'⚙️ Починить катушку'}[key])+' · '+cost+' 🪙'}}}
function renderAll(){renderHeader();renderSurvival();renderDurability();renderBaits();renderSpots();renderShop();renderKeep();renderTasks();renderPendingCatch();$('castBtn').disabled=mode==='bite'||mode==='fight'||!!state.pendingCatch||state.rodDurability<=0;$('reelBtn').disabled=mode!=='bite'&&mode!=='fight'}
