let survivalLast=0,survivalHudTick=0,survivalSaveTick=0;
function updateSurvival(now){if(!survivalLast)survivalLast=now;const dt=Math.min(1,Math.max(0,(now-survivalLast)/1000));survivalLast=now;state.gameMinutes=(Number(state.gameMinutes)||360)+dt*2.4;state.hunger=Math.max(0,state.hunger-dt*.025);if(state.hunger<=0)state.health=Math.max(0,state.health-dt*.12);survivalHudTick+=dt;survivalSaveTick+=dt;if(survivalHudTick>=1){survivalHudTick=0;renderSurvival();if($('gameClock'))$('gameClock').textContent=gameClockText()}if(survivalSaveTick>=15){survivalSaveTick=0;try{localStorage.setItem('odyssey-save',JSON.stringify(state))}catch{}}}
function gameLoop(now){updateFight(now);updateSurvival(now);requestAnimationFrame(gameLoop)}
